#include <cmath>
#include <cstdint>
#include <cstring>
#include <map>
#include <optional>
#include <vector>

struct Region { std::uint64_t base; std::vector<std::uint8_t> bytes; };
using Snapshot = std::vector<Region>;

enum class Type { Int32, Float, Double };
enum class Compare { Exact, Changed, Unchanged, Increased, Decreased, IncreasedBy, DecreasedBy };

class Scanner
{
public:
    explicit Scanner(Type type) : type{ type }, size{ type == Type::Double ? 8u : 4u } {}

    void firstScan(const Snapshot& memory, double value)
    {
        found.clear();
        each(memory, [&](std::uint64_t address, double v) { if (matches(v, value)) found[address] = v; });
    }

    void firstScanUnknown(const Snapshot& memory)
    {
        found.clear();
        each(memory, [&](std::uint64_t address, double v) { found[address] = v; });
    }

    void nextScan(const Snapshot& memory, Compare how, double value = 0)
    {
        std::map<std::uint64_t, double> kept;
        for (const auto& [address, previous] : found)
        {
            const auto now{ read(memory, address) };
            if (!now) continue;
            bool keep{ false };
            switch (how)
            {
            case Compare::Exact: keep = matches(*now, value); break;
            case Compare::Changed: keep = *now != previous; break;
            case Compare::Unchanged: keep = *now == previous; break;
            case Compare::Increased: keep = *now > previous; break;
            case Compare::Decreased: keep = *now < previous; break;
            case Compare::IncreasedBy: keep = matches(*now - previous, value); break;
            case Compare::DecreasedBy: keep = matches(previous - *now, value); break;
            }
            if (keep) kept[address] = *now;
        }
        found = std::move(kept);
    }

    std::vector<std::uint64_t> results() const
    {
        std::vector<std::uint64_t> out;
        for (const auto& entry : found) out.push_back(entry.first);
        return out;
    }

    std::optional<double> read(const Snapshot& memory, std::uint64_t address) const
    {
        if (address % size != 0) return std::nullopt;
        for (const Region& r : memory)
        {
            if (address < r.base || address - r.base + size > r.bytes.size()) continue;
            return decode(&r.bytes[address - r.base]);
        }
        return std::nullopt;
    }

private:
    Type type;
    std::uint32_t size;
    std::map<std::uint64_t, double> found;

    double decode(const std::uint8_t* p) const
    {
        if (type == Type::Int32) { std::int32_t v; std::memcpy(&v, p, 4); return v; }
        if (type == Type::Float) { float v; std::memcpy(&v, p, 4); return v; }
        double v; std::memcpy(&v, p, 8); return v;
    }

    bool matches(double a, double b) const
    {
        return type == Type::Int32 ? a == b : std::fabs(a - b) <= 0.001;
    }

    template <typename F>
    void each(const Snapshot& memory, F visit) const
    {
        for (const Region& r : memory)
        {
            const std::uint64_t first{ (r.base + size - 1) / size * size };
            for (std::uint64_t a{ first }; a + size <= r.base + r.bytes.size(); a += size)
                visit(a, decode(&r.bytes[a - r.base]));
        }
    }
};

unitTests:
#include <cstring>
using U = std::vector<std::uint64_t>;
static void putI(Region& r, std::uint64_t address, std::int32_t v) { std::memcpy(&r.bytes[address - r.base], &v, 4); }
static void putF(Region& r, std::uint64_t address, float v) { std::memcpy(&r.bytes[address - r.base], &v, 4); }
static void putD(Region& r, std::uint64_t address, double v) { std::memcpy(&r.bytes[address - r.base], &v, 8); }

// Two heap regions; health lives at 0x2010, a decoy 87 at 0x2018 and another at 0x5000.
static Snapshot game(int health, int decoy)
{
    Region a{ 0x2000, std::vector<std::uint8_t>(0x40, 0) };
    Region b{ 0x5000, std::vector<std::uint8_t>(0x10, 0) };
    putI(a, 0x2010, health);
    putI(a, 0x2018, decoy);
    putI(b, 0x5000, 87);
    return { a, b };
}

TEST("exact scans narrow down") {
    Scanner s{ Type::Int32 };
    s.firstScan(game(87, 87), 87);
    CHECK_EQ(s.results(), (U{ 0x2010, 0x2018, 0x5000 }));
    s.nextScan(game(72, 87), Compare::Exact, 72);
    CHECK_EQ(s.results(), (U{ 0x2010 }));
}
TEST("changed, unchanged, increased, decreased") {
    Scanner s{ Type::Int32 };
    s.firstScan(game(87, 87), 87);
    s.nextScan(game(72, 87), Compare::Decreased);
    CHECK_EQ(s.results(), (U{ 0x2010 }));
    Scanner t{ Type::Int32 };
    t.firstScan(game(87, 87), 87);
    t.nextScan(game(87, 90), Compare::Unchanged);
    CHECK_EQ(t.results(), (U{ 0x2010, 0x5000 }));
    t.nextScan(game(100, 90), Compare::Increased);
    CHECK_EQ(t.results(), (U{ 0x2010 }));
    t.nextScan(game(100, 90), Compare::Changed);
    CHECK(t.results().empty());
}
TEST("unknown values and by-amount scans") {
    Scanner s{ Type::Int32 };
    s.firstScanUnknown(game(50, 7));
    CHECK_EQ(s.results().size(), 20u);
    s.nextScan(game(35, 7), Compare::DecreasedBy, 15);
    CHECK_EQ(s.results(), (U{ 0x2010 }));
    s.nextScan(game(40, 7), Compare::IncreasedBy, 5);
    CHECK_EQ(s.results(), (U{ 0x2010 }));
}
TEST("floats with a tolerance") {
    Region r{ 0x8000, std::vector<std::uint8_t>(0x20, 0) };
    putF(r, 0x8004, 86.9996f);
    putF(r, 0x8008, 87.5f);
    Scanner s{ Type::Float };
    s.firstScan({ r }, 87.0);
    CHECK_EQ(s.results(), (U{ 0x8004 }));
    CHECK_EQ(static_cast<float>(s.read({ r }, 0x8004).value_or(0)), 86.9996f);
    CHECK(!s.read({ r }, 0x8006).has_value());
}
TEST("doubles, alignment and regions") {
    Region r{ 0x9004, std::vector<std::uint8_t>(0x1C, 0) };
    putD(r, 0x9008, 2.5);
    putD(r, 0x9018, 2.5);
    Scanner s{ Type::Double };
    s.firstScan({ r }, 2.5);
    CHECK_EQ(s.results(), (U{ 0x9008, 0x9018 }));
    s.nextScan({ Region{ 0x9004, std::vector<std::uint8_t>(0x0C, 0) } }, Compare::Unchanged);
    CHECK(s.results().empty());
    Scanner unknown{ Type::Double };
    unknown.firstScanUnknown({ r });
    CHECK_EQ(unknown.results(), (U{ 0x9008, 0x9010, 0x9018 }));
}

